/* ============================================================
   Application -- Native Overcharge execution
   ============================================================ */

async function executeNativeFrameConnOvercharge(
  application,
  state,
  registry
) {
  const overchargeAction =
    registry.get(
      "special.overcharge"
    );


  if (
    !overchargeAction
  ) {
    throw new Error(
      "Frame Conn could not resolve the Overcharge action."
    );
  }


  const permission =
    state.canUseAction(
      overchargeAction
    );


  if (
    !permission.allowed
  ) {
    throw new Error(
      permission.reason ??
      "Overcharge is not available."
    );
  }


  const token =
    application.getControlledToken();

  const actor =
    token?.actor ??
    null;


  if (
    !actor
  ) {
    throw new Error(
      "Select the mech token that should Overcharge."
    );
  }


  const nativeHeatFormula =
    typeof actor
      .strussHelper
      ?.getOverchargeRoll ===
      "function"
      ? actor.strussHelper
          .getOverchargeRoll()
      : null;


  const nativeResult =
    await executeFrameConnApplicationActionRoll(
      actor,
      overchargeAction
    );


  if (
    nativeResult === false
  ) {
    throw new Error(
      "Native Lancer Overcharge did not complete."
    );
  }


  state.useOvercharge({
    heatFormula:
      nativeHeatFormula
  });


  return {
    actor,
    heatFormula:
      nativeHeatFormula,
    nativeResult
  };
}


